// No build dependencies. Both outputs use the existing server resource whitelist.
import {readFile,writeFile} from 'node:fs/promises';
const here = path => new URL(path, import.meta.url);
const [vendor, motion, form, css, image, portal] = await Promise.all([
  readFile(here('./vendor/gsap/dist/gsap.min.js'), 'utf8'),
  readFile(here('./client/login-motion.mjs'), 'utf8'),
  readFile(here('./client/login-form.mjs'), 'utf8'),
  readFile(here('./client/login.css'), 'utf8'),
  readFile(here('./client/sandbox-pattern.jpg')),
  readFile(here('../ui-motion/login-portal.mjs'), 'utf8'),
]);
const engine = vendor.replace(/\/\/# sourceMappingURL=.*$/gm, '').replace(/[ \t]+$/gm, '');
await writeFile(here('./public/login.mjs'),
  '// Generated by node admin-access/build-login.mjs. Edit client/ sources.\n' +
  'function loadLoginGsap() {\nconst module = {exports: {}}; const exports = module.exports;\n' + engine +
  '\nreturn module.exports.gsap;\n}\n' + portal + '\n' + motion +
  '\nlet loginMotion = null;\ntry { loginMotion = createLoginMotion({gsap: loadLoginGsap()}); } catch { /* Keep the form usable if decorative motion fails. */ }\n' +
  '\n// Existing authentication logic, scoped separately from the animation.\n{\n' + form + '\n}\n');
await writeFile(here('./public/login.css'),
  '/* Generated by node admin-access/build-login.mjs. Edit client/login.css. */\n' + css +
  '\n:root { --campus-pattern: url("data:image/jpeg;base64,' + image.toString('base64') + '"); }\n');
console.log('Login assets built with local GSAP 3.15.0.');
